function renderProcess(){modeToolbar([]);compareToolbar(false);const labels=currentModule.labels||[],active=S.values.active||0;const graph=`<div class="flowWrap"><div class="processRow">${labels.map((l,i)=>`${i?'<div class="processArrow">→</div>':''}<button class="processBox ${i===active?'active':''}" data-step="${i}">${i+1}. ${l}</button>`).join('')}</div></div>`;const side=`<div class="sideTitle"><b>Fazele activității</b></div><div class="panelSection"><div class="help">Selectează o fază pentru a o evidenția. Succesiunea din suport: producție → repartiție → schimb → consum.</div></div>`;$('#content').innerHTML=baseShell(graph,side,metric('Faza selectată',labels[active]||'—'),'Fazele activității economice sunt interdependente și formează un circuit.');attachExplain();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{S.values.active=+b.dataset.step;persist();render()})}


